cards.solution:
const latar = document.querySelector("#latar");
const status = document.querySelector("#status");
latar.addEventListener("click", (e) => {
  if (e.target !== latar) return;
  latar.hidden = true;
  status.textContent = "Dialog ditutup";
});
document.querySelector("#batal").click();
console.log(status.textContent);
latar.click();
console.log(status.textContent, latar.hidden);
